bool parseRosterElement(const char* text, size_t len, roster::Entry& out) {
  if (text == nullptr) {
    return false;
  }

  Field fields[4] = {};
  if (!splitFields(text, len, fields)) {
    return false;
  }

  // Into a scratch entry, so a refusal leaves `out` untouched — a caller that
  // reuses one Entry across elements must not inherit half of a bad one.
  roster::Entry entry;
  uint32_t opensIn = 0U;
  uint32_t closesIn = 0U;
  if (!parseToken(text, fields[0], entry.token, sizeof(entry.token)) ||
      !parseRelay(text, fields[1], entry.court) || !parseOpensIn(text, fields[2], opensIn) ||
      !parseSeconds(text, fields[3], closesIn)) {
    return false;
  }
  if (closesIn < opensIn) {
    return false; // ends before it starts
  }

  entry.opensAtMs = opensIn * 1000U;
  entry.closesAtMs = closesIn * 1000U;
  entry.durationMs = entry.closesAtMs - entry.opensAtMs;
  entry.valid = true;
  out = entry;
  return true;
}

bool parseRosterElement(const char* text, roster::Entry& out) {
  if (text == nullptr) {
    return false;
  }
  return parseRosterElement(text, strlen(text), out);
}

bool parseCourtNumbers(const char* body, size_t len, int16_t out[kMaxCourts], uint8_t& count) {
  // THE TOP-LEVEL `court_numbers`, for the reason applyRoster reads the
  // top-level `roster` (round G4, B2). This array decides which club court each
  // RELAY is — what a walk-up is sold as, and what the power-dip restore gates
  // on — and the flat scan returns the first match in document order, so a
  // decoy placed before the real field wins. A box that adopted one would map
  // relay 0 to somebody else's court and sell a member court time the club
  // never booked.
  //
  // Narrowing this is safe for the same reason it was safe for the roster: the
  // contract puts `court_numbers` at the top level. The NESTED reads — the
  // button map, the slice minutes, the walk-up maximum, all out of `config` —
  // still use the flat scan, deliberately and documented, and must not be
  // narrowed with it.
  size_t at = devapi::json::findTopLevelArray(body, len, "court_numbers");
  if (at == devapi::json::kNotFound) {
    return false;
  }

  int16_t parsed[kMaxCourts] = {};
  uint8_t n = 0U;
  uint32_t value = 0U;
  while (devapi::json::nextUnsignedElement(body, len, at, value)) {
    if (n == kMaxCourts || value > static_cast<uint32_t>(INT16_MAX)) {
      // A fifth court, or a number no court has. The whole list is refused
      // rather than the first four kept: a box that drives relays 0-3 and is
      // told about five courts is a box whose configuration is wrong, and
      // guessing which four is how court D lights for court E's booking.
      return false;
    }
    parsed[n] = static_cast<int16_t>(value);
    ++n;
  }

  // The walker stops at `]` or at something it cannot read. Only the bracket
  // is a complete list.
  if (at >= len || body[at] != ']') {
    return false;
  }

  for (uint8_t i = 0U; i < kMaxCourts; ++i) {
    out[i] = i < n ? parsed[i] : 0;
  }
  count = n;
  return true;
}

